use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut freq_map: std::collections::HashMap<String, i64> = std::collections::HashMap::new();

    for item in arr {
        let str_val = item.as_str().unwrap();
        *freq_map.entry(str_val.to_string()).or_insert(0) += 1;
    }

    Value::Object(freq_map.into_iter().map(|(k, v)| (k.to_string(), Value::from(v))).collect())
}
